import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Parallasse secondo","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/i_trigonometria/ie/iecc.md","filePath":"lezioni/i_trigonometria/ie/iecc.md"}`),a={name:`lezioni/i_trigonometria/ie/iecc.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="parallasse-secondo" tabindex="-1">Parallasse secondo <a class="header-anchor" href="#parallasse-secondo" aria-label="Permalink to “Parallasse secondo”">​</a></h1><p>Ora possiamo usare la distanza Terra-Sole trovata per costruire un&#39;unità di misura astronomica: il Parsec (o parallasse secondo).</p><p>Consideriamo un giorno dell&#39;anno e poi consideriamo il giorno che cade sei mesi dopo; avremo che la Terra si trova in punti opposti <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>T</mi></mrow><annotation encoding="application/x-tex">T</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span> e <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>T</mi><mo mathvariant="normal" lspace="0em" rspace="0em">′</mo></msup></mrow><annotation encoding="application/x-tex">T&#39;</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.7519em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span></span></span></span> rispetto alla sua orbita attorno al Sole (l&#39;orbita è quasi circolare).</p><p>Se osserviamo la stella Alfa del Centauro vediamo che tra sei mesi prima e sei mesi dopo notiamo una differenza di posizione: poco più di un secondo di grado. Questo sarà dovuto al fatto che, procedendo la Terra nella sua orbita, dopo sei mesi sembrerà che la stella si sia mossa sulla sfera celeste; essendo la stella fissa la variazione è dovuta all&#39;orbita terrestre.</p><p>Quindi possiamo considerare il triangolo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>T</mi><msup><mi>T</mi><mo mathvariant="normal" lspace="0em" rspace="0em">′</mo></msup><mi>A</mi></mrow><annotation encoding="application/x-tex">TT&#39;A</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.7519em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span><span class="mord mathnormal">A</span></span></span></span> dato dalle due posizioni della Terra e con un angolo di un secondo di grado per definire un&#39;unità di misura.</p><blockquote><p><strong>Nota:</strong> Al solito dovrei fare un triangolo lunghissimo e stretto, perché l&#39;angolo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi></mrow><annotation encoding="application/x-tex">A</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span></span></span></span> sia di un secondo di grado, ma ciò è graficamente impossibile, quindi la figura è solamente per capire il ragionamento.</p></blockquote><p>In astronomia si definisce parallasse l&#39;angolo secondo cui da un punto si vede il diametro dell&#39;orbita della Terra attorno al Sole.</p><h2 id="definizione" tabindex="-1">Definizione <a class="header-anchor" href="#definizione" aria-label="Permalink to “Definizione”">​</a></h2><p><strong>Parsec</strong> (o Parallasse secondo) è la distanza di un oggetto da cui si vede il diametro dell&#39;orbita della Terra attorno al Sole con l&#39;angolo di un secondo di grado.</p><p>Oggi il Parsec non si usa più, sostituito dall&#39;anno luce. Siccome la luce viaggia nel vuoto sempre con velocità costante di circa <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>299</mn><mtext> </mtext><mn>792</mn><mo separator="true">,</mo><mn>458</mn><mtext>\xA0km/s</mtext></mrow><annotation encoding="application/x-tex">299\\,792,458\\text{ km/s}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">299</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">792</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">458</span><span class="mord text"><span class="mord">\xA0km/s</span></span></span></span></span>, un anno luce vale:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mn>299</mn><mtext> </mtext><mn>792</mn><mo separator="true">,</mo><mn>458</mn><mtext>\xA0km</mtext><mo>⋅</mo><mn>60</mn><mtext>\xA0s</mtext><mo>⋅</mo><mn>60</mn><mtext>\xA0min</mtext><mo>⋅</mo><mn>24</mn><mtext>\xA0h</mtext><mo>⋅</mo><mn>365</mn><mtext>\xA0giorni</mtext></mrow><annotation encoding="application/x-tex">299\\,792,458\\text{ km} \\cdot 60\\text{ s} \\cdot 60\\text{ min} \\cdot 24\\text{ h} \\cdot 365\\text{ giorni} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord">299</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">792</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">458</span><span class="mord text"><span class="mord">\xA0km</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">60</span><span class="mord text"><span class="mord">\xA0s</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6679em;"></span><span class="mord">60</span><span class="mord text"><span class="mord">\xA0min</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord">24</span><span class="mord text"><span class="mord">\xA0h</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8623em;vertical-align:-0.1944em;"></span><span class="mord">365</span><span class="mord text"><span class="mord">\xA0giorni</span></span></span></span></span></span></p><p>O meglio, essendo un anno di 365 giorni, 6 ore, 24 minuti ecc.:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mn>1</mn><mtext>\xA0anno\xA0luce</mtext><mo>=</mo><mn>299</mn><mtext> </mtext><mn>792</mn><mo separator="true">,</mo><mn>458</mn><mo>⋅</mo><mn>60</mn><mtext>\xA0s</mtext><mo>⋅</mo><mn>60</mn><mtext>\xA0min</mtext><mo>⋅</mo><mn>24</mn><mtext>\xA0h</mtext><mo>⋅</mo><mn>365</mn><mo separator="true">,</mo><mn>25</mn><mtext>\xA0giorni</mtext><mo>≈</mo><mn>9.460.730.473.000</mn><mtext>\xA0km</mtext></mrow><annotation encoding="application/x-tex">1\\text{ anno luce} = 299\\,792,458 \\cdot 60\\text{ s} \\cdot 60\\text{ min} \\cdot 24\\text{ h} \\cdot 365,25\\text{ giorni} \\approx 9.460.730.473.000\\text{ km} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord">1</span><span class="mord text"><span class="mord">\xA0anno\xA0luce</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">299</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">792</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">458</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">60</span><span class="mord text"><span class="mord">\xA0s</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6679em;"></span><span class="mord">60</span><span class="mord text"><span class="mord">\xA0min</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord">24</span><span class="mord text"><span class="mord">\xA0h</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8623em;vertical-align:-0.1944em;"></span><span class="mord">365</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">25</span><span class="mord text"><span class="mord">\xA0giorni</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord">9.460.730.473.000</span><span class="mord text"><span class="mord">\xA0km</span></span></span></span></span></span></p><p>Abbiamo che:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mn>1</mn><mtext>\xA0parsec</mtext><mo>≈</mo><mn>3</mn><mo separator="true">,</mo><mn>26</mn><mtext>\xA0anni\xA0luce</mtext></mrow><annotation encoding="application/x-tex">1\\text{ parsec} \\approx 3,26\\text{ anni luce} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">1</span><span class="mord text"><span class="mord">\xA0parsec</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord">3</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">26</span><span class="mord text"><span class="mord">\xA0anni\xA0luce</span></span></span></span></span></span></p>`,15)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};